// Making one prototype: its copy of the code (it runs meanwhile, so the
// team watches it change), the maker asked with the explore skill, its own
// tool to look and a browser to click through it, in the conversation it
// keeps for that prototype; then started again so the newest runs, made to
// look once when it did not, and what it made committed, pushed and told
// (made.ts).
import { readFileSync, writeFileSync } from "node:fs";
import { doingOf, makerModel, } from "@software-factory/core";
import { versionCopy, versionWorkspace } from "../../prototypes/copies.js";
import { lookAndFix } from "./looks.js";
import { finishMaking } from "./made.js";
import { askerFor } from "./maker-desk.js";
import { askFor } from "./making-words.js";
import { dropAsked, keepAsked } from "./cut-off.js";
import { codeMaps } from "./product-picture.js";
// The maker's browser, open while it makes the prototype; without one (none
// could start) it still makes it, and only looks at pictures.
export async function makeOne(on) {
    const browser = on.browser ? await on.browser().catch(() => null) : null;
    try {
        await makeWith(on, browser);
    }
    finally {
        browser?.close();
        dropAsked(on.project, on.exploration.id, on.made);
    }
}
async function makeWith(on, browser) {
    const { mode, desk, exploration, made, change } = on;
    const { key } = made;
    const copy = versionCopy(on.project, exploration.id, key, made.branch);
    const workspace = await versionWorkspace(on.project, copy);
    // No start command yet: Tinker works one out first (once, for the whole
    // team), so the prototype can run while it is made.
    if (!mode.canStart())
        await on.setUp();
    // It runs while it is made: the team watches it change.
    if (mode.canStart())
        mode.start(exploration.id, key).catch(() => undefined);
    // The conversation and what was asked are saved beside the copy at once,
    // so a maker the server closed on continues them after its restart.
    const savedAt = `${copy.folder}.maker-session`;
    const session = sessionKept(on, savedAt);
    const ask = askerFor({
        claude: on.claude,
        folder: copy.folder,
        model: makerModel(on.root),
        session,
        mcp: desk.mcpFor(exploration.id, key),
        browser: browser
            ? { name: "browser", url: browser.url, headers: {} }
            : undefined,
        onStep: stepsInto(mode, exploration.id, key),
        onFresh: (fresh) => {
            desk.use(exploration.id, key, fresh);
            saveSession(savedAt, fresh);
        },
    });
    const asked = askFor(exploration, on.board, made, {
        change,
        resumed: on.resumed === true,
        maps: codeMaps(on.root, on.project),
    });
    let result;
    try {
        const first = await ask(asked, false);
        // Started again, so what runs is the newest, server and all (a page
        // reloads by itself as files change, a server does not).
        await mode.stop(exploration.id, key);
        result = await lookAndFix(first, {
            ask: (prompt) => ask(prompt, true),
            look: on.look,
            looked: () => desk.hasLooked(exploration.id, key),
            opens: (page) => {
                on.mark({ opens: page });
            },
            states: (states) => {
                on.mark({ states });
            },
        });
    }
    finally {
        saveSession(savedAt, desk.done(exploration.id, key));
    }
    on.mark({});
    await finishMaking({
        mode,
        workspace,
        exploration: exploration.id,
        made,
        change,
        result,
        ready: on.ready,
        failed: on.failed,
        look: on.look,
    });
}
// The maker's conversation (the one it had, after a restart) and what it is
// asked, both saved before it starts.
function sessionKept(on, savedAt) {
    const { exploration, made } = on;
    const session = on.desk.sessionFor(exploration.id, made.key, savedSession(savedAt));
    saveSession(savedAt, session.id);
    keepAsked(on.project, exploration.id, made, on.change);
    return session;
}
// Each step the maker takes, kept with the prototype's run (the last 60).
export function stepsInto(mode, exploration, key) {
    return (line) => {
        const { steps } = mode.runOf(exploration, key);
        // A line that is not an action (the kobold's own words) leaves the kind.
        const doing = doingOf(line);
        mode.set(exploration, key, {
            activity: line.slice(0, 80),
            ...(doing ? { doing } : {}),
            steps: [...steps, line.slice(0, 200)].slice(-60),
        });
    };
}
function savedSession(file) {
    try {
        const id = readFileSync(file, "utf8").trim();
        return /^[\w-]+$/.test(id) ? id : null;
    }
    catch {
        return null;
    }
}
function saveSession(file, session) {
    if (!session)
        return;
    try {
        writeFileSync(file, session);
    }
    catch {
        // Not saved: the next maker after a restart starts a new conversation.
    }
}
